mapper.update:
UPDATE logan_alert_rule
name=#{name}, metric=#{metric}, op_type=#{opType}, threshold=#{threshold}, window_minutes=#{windowMinutes}, platform=#{platform}, app_version=#{appVersion}, webhook=#{webhook}, enabled=#{enabled}, cooldown_minutes=#{cooldownMinutes}, update_time=#{updateTime}
WHERE id=#{id}

mapper.select:
SELECT r.id, r.rule_id AS ruleId, r.app_id AS appId, r.metric, r.value, r.threshold,
       r.window_begin AS windowBegin, r.window_end AS windowEnd, r.webhook_result AS webhookResult,
       r.payload, r.add_time AS addTime, a.name AS ruleName, a.op_type AS opType
FROM logan_alert_record r LEFT JOIN logan_alert_rule a ON a.id = r.rule_id

    AND r.app_id=#{appId}
    AND r.rule_id=#{ruleId}

ORDER BY r.add_time DESC LIMIT #{limit}

SELECT  FROM logan_alert_rule

    AND app_id=#{appId}
    AND enabled=#{enabled}

ORDER BY enabled DESC, id DESC LIMIT #{limit}

SELECT COUNT(*) FROM logan_crash_issue i
WHERE i.first_crash_time BETWEEN #{q.beginTime} AND #{q.endTime}
AND i.app_id=#{q.appId}
AND i.platform=#{q.platform}
AND EXISTS (SELECT 1 FROM logan_crash c WHERE c.fingerprint = i.fingerprint AND c.app_version = #{q.appVersion})

SELECT COUNT(*) FROM logan_http_issue i
WHERE i.first_seen BETWEEN #{q.beginTime} AND #{q.endTime}
AND i.app_id=#{q.appId}
AND i.platform=#{q.platform}
